def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos2(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos2(observation.get("self_position", (0, 0)))
    ox, oy = pos2(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = max(corners, key=lambda c: dist(c, opp_pos)) if corners else self_pos
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = None
        best_score = None
        for t in targets:
            tp = pos2(t, None)
            if tp is None:
                continue
            score = dist(self_pos, tp)
            if best is None or score < best_score:
                best = tp
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for r in resources:
        rp = pos2(r, None)
        if rp is None:
            continue
        score = dist(self_pos, rp)
        if best is None or score < best_score:
            best = rp
            best_score = score
    if best is not None:
        return step_toward(self_pos, best)

    return step_away(self_pos, opp_pos)

